import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Collect inputs from user
        System.out.print("Principal ($): ");           double P = sc.nextDouble(); // starting amount
        System.out.print("Annual rate (e.g. 0.05): "); double r = sc.nextDouble(); // rate as decimal
        System.out.print("Times/year compounded: ");   int    n = sc.nextInt();    // e.g. 12 = monthly
        System.out.print("Years: ");                   int    t = sc.nextInt();    // investment duration
        sc.close();

        // Apply formula: A = P * (1 + r/n)^(n*t)
        double A = P * Math.pow(1 + r / n, n * t); // A = final amount
        System.out.printf("Final amount:    $%.2f%n", A);
        System.out.printf("Interest earned: $%.2f%n", A - P); // interest = A minus principal
    }
}

