double result = 0;
boolean valid = true;

switch (op) {
    case "+" -> result = a + b;
    case "-" -> result = a - b;
    case "*" -> result = a * b;
    case "/" -> {
        if (b == 0) {
            System.out.println("Error: cannot divide by zero.");
            valid = false;
        } else { result = a / b; }
    }
    default -> { System.out.println("Unknown operator: " + op); valid = false; }
}

if (valid) {
    System.out.printf("%.2f %s %.2f = %.2f%n", a, op, b, result);
}

// Extended switch — add modulus and power
switch (op) {
    case "+" -> result = a + b;
    case "-" -> result = a - b;
    case "*" -> result = a * b;
    case "/" -> {
        if (b == 0) { System.out.println("Div by zero!"); valid = false; result = 0; }
        else result = a / b;
    }
    case "%" -> result = a % b;
    case "^" -> result = Math.pow(a, b);
    default  -> { System.out.println("Unknown operator."); valid = false; result = 0; }
}

