    if (i % 2 == 0) {
        System.out.println("First even: " + i);  // 2
        break;
    }
}

// continue — skip even numbers, print only odd
for (int i = 1; i <= 10; i++) {
    if (i % 2 == 0) continue;
    System.out.print(i + " ");  // 1 3 5 7 9
}

// Outer runs 3 times; inner runs 3 times per outer — 9 total
