public class GuessingGame {
    public static void main(String[] args) {
        Scanner sc     = new Scanner(System.in);
        Random  random = new Random();

        int secret  = random.nextInt(100) + 1;  // 1 to 100
        int guess   = 0;
        int counter = 0;

        System.out.println("Guess a number between 1 and 100:");
        // Game loop — see next slide
        sc.close();
    }
}

while (guess != secret) {
    System.out.print("Guess #" + (counter + 1) + ": ");
    guess = sc.nextInt();
    counter++;

    if      (guess < secret) System.out.println("Too low!");
    else if (guess > secret) System.out.println("Too high!");
    else System.out.println("Correct! Guessed in " + counter + " tries.");
}

int maxGuesses = 7;
boolean won    = false;

while (counter < maxGuesses && !won) {
    System.out.print("Guess " + (counter + 1) + "/" + maxGuesses + ": ");
    guess = sc.nextInt();
    counter++;

    if      (guess < secret) System.out.println("Too low!");
    else if (guess > secret) System.out.println("Too high!");
    else { System.out.println("You won in " + counter + " tries!"); won = true; }
}

if (!won) System.out.println("Game over! The number was " + secret + ".");

