public class BankAccount {
    // (deposit, withdraw, checkBalance from previous slide)

    public static void main(String[] args) {
        Scanner sc      = new Scanner(System.in);
        double  balance = 1000.00;
        int     choice;

        do {
            System.out.println("\n1. Deposit  2. Withdraw  3. Balance  4. Quit");
            System.out.print("Choice: ");
            choice = sc.nextInt();

            switch (choice) {
                case 1 -> { System.out.print("Amount: $"); balance = deposit(balance,  sc.nextDouble()); }
                case 2 -> { System.out.print("Amount: $"); balance = withdraw(balance, sc.nextDouble()); }
                case 3 -> checkBalance(balance);
                case 4 -> System.out.println("Goodbye!");
                default -> System.out.println("Invalid option.");
            }
        } while (choice != 4);
        sc.close();
    }
}

